/* Skin "doom-64" (Doom 64): the tweakcn preset "doom-64" (Apache-2.0, see NOTICE.md), written by packages/skins/tools/tweakcn-skins.ts.
   On when data-skin="doom-64" is on <html> (the page) or on any element (a tile of /skins/). Values as tweakcn exports them;
   the spacing scale stays the kit's 0.25rem. Fonts: Oxanium (Google Fonts, loaded when the skin is on). */
[data-skin="doom-64"] {
  --background: hsl(0 0% 80%);
  --foreground: hsl(0 0% 12%);
  --card: hsl(0 0% 69%);
  --card-foreground: hsl(0 0% 12%);
  --popover: hsl(0 0% 69%);
  --popover-foreground: hsl(0 0% 12%);
  --primary: hsl(0 73.5% 41.4%);
  --primary-foreground: hsl(0 0% 100%);
  --secondary: hsl(82 39% 30%);
  --secondary-foreground: hsl(0 0% 100%);
  --muted: hsl(0 0% 72%);
  --muted-foreground: hsl(0 0% 26%);
  --accent: hsl(207 47.2% 45.3%);
  --accent-foreground: hsl(0 0% 100%);
  --destructive: hsl(26 100% 50%);
  --destructive-foreground: hsl(0 0% 0%);
  --border: hsl(0 0% 31%);
  --input: hsl(0 0% 31%);
  --ring: hsl(0 73.5% 41.4%);
  --chart-1: hsl(0 73.5% 41.4%);
  --chart-2: hsl(82 39% 30%);
  --chart-3: hsl(207 44% 49%);
  --chart-4: hsl(26 100% 50%);
  --chart-5: hsl(16 18% 47%);
  --sidebar: hsl(0 0% 69%);
  --sidebar-foreground: hsl(0 0% 12%);
  --sidebar-primary: hsl(0 73.5% 41.4%);
  --sidebar-primary-foreground: hsl(0 0% 100%);
  --sidebar-accent: hsl(207 44% 49%);
  --sidebar-accent-foreground: hsl(0 0% 100%);
  --sidebar-border: hsl(0 0% 31%);
  --sidebar-ring: hsl(0 73.5% 41.4%);
  --font-sans: "Oxanium", sans-serif;
  --font-serif: ui-serif, Georgia, Cambria, "Times New Roman", Times, serif;
  --font-mono: "Source Code Pro", monospace;
  --radius: 0px;
  --shadow-2xs: 0px 2px 4px 0px hsl(0 0% 0% / 0.20);
  --shadow-xs: 0px 2px 4px 0px hsl(0 0% 0% / 0.20);
  --shadow-sm: 0px 2px 4px 0px hsl(0 0% 0% / 0.40), 0px 1px 2px -1px hsl(0 0% 0% / 0.40);
  --shadow: 0px 2px 4px 0px hsl(0 0% 0% / 0.40), 0px 1px 2px -1px hsl(0 0% 0% / 0.40);
  --shadow-md: 0px 2px 4px 0px hsl(0 0% 0% / 0.40), 0px 2px 4px -1px hsl(0 0% 0% / 0.40);
  --shadow-lg: 0px 2px 4px 0px hsl(0 0% 0% / 0.40), 0px 4px 6px -1px hsl(0 0% 0% / 0.40);
  --shadow-xl: 0px 2px 4px 0px hsl(0 0% 0% / 0.40), 0px 8px 10px -1px hsl(0 0% 0% / 0.40);
  --shadow-2xl: 0px 2px 4px 0px hsl(0 0% 0% / 1.00);
  --destructive-hover: hsl(26 100% 56%);
}

:is(.dark, [data-theme="dark"]) [data-skin="doom-64"],
[data-skin="doom-64"]:is(.dark, [data-theme="dark"]) {
  --background: hsl(0 0% 10%);
  --foreground: hsl(0 0% 88%);
  --card: hsl(0 0% 16.5%);
  --card-foreground: hsl(0 0% 88%);
  --popover: hsl(0 0% 16.5%);
  --popover-foreground: hsl(0 0% 88%);
  --primary: hsl(0.7 72% 52.4%);
  --primary-foreground: hsl(0 0% 100%);
  --secondary: hsl(92 48% 42%);
  --secondary-foreground: hsl(0 0% 0%);
  --muted: hsl(0 0% 14.5%);
  --muted-foreground: hsl(0 0% 63%);
  --accent: hsl(207 89% 68%);
  --accent-foreground: hsl(0 0% 0%);
  --destructive: hsl(37.6 100% 50%);
  --destructive-foreground: hsl(0 0% 0%);
  --border: hsl(0 0% 29%);
  --input: hsl(0 0% 29%);
  --ring: hsl(1.4 77.2% 55.3%);
  --chart-1: hsl(1.4 77.2% 55.3%);
  --chart-2: hsl(92 48% 42%);
  --chart-3: hsl(207 89% 68%);
  --chart-4: hsl(37.6 100% 50%);
  --chart-5: hsl(16 15% 56%);
  --sidebar: hsl(0 0% 8%);
  --sidebar-foreground: hsl(0 0% 88%);
  --sidebar-primary: hsl(1.4 77.2% 55.3%);
  --sidebar-primary-foreground: hsl(0 0% 100%);
  --sidebar-accent: hsl(207 89% 68%);
  --sidebar-accent-foreground: hsl(0 0% 0%);
  --sidebar-border: hsl(0 0% 29%);
  --sidebar-ring: hsl(1.4 77.2% 55.3%);
  --shadow-2xs: 0px 2px 5px 0px hsl(0 0% 0% / 0.30);
  --shadow-xs: 0px 2px 5px 0px hsl(0 0% 0% / 0.30);
  --shadow-sm: 0px 2px 5px 0px hsl(0 0% 0% / 0.60), 0px 1px 2px -1px hsl(0 0% 0% / 0.60);
  --shadow: 0px 2px 5px 0px hsl(0 0% 0% / 0.60), 0px 1px 2px -1px hsl(0 0% 0% / 0.60);
  --shadow-md: 0px 2px 5px 0px hsl(0 0% 0% / 0.60), 0px 2px 4px -1px hsl(0 0% 0% / 0.60);
  --shadow-lg: 0px 2px 5px 0px hsl(0 0% 0% / 0.60), 0px 4px 6px -1px hsl(0 0% 0% / 0.60);
  --shadow-xl: 0px 2px 5px 0px hsl(0 0% 0% / 0.60), 0px 8px 10px -1px hsl(0 0% 0% / 0.60);
  --shadow-2xl: 0px 2px 5px 0px hsl(0 0% 0% / 1.50);
  --destructive-hover: hsl(37.6 100% 56%);
}

[data-skin="doom-64"] .shadow-xs { --tw-shadow: var(--shadow-xs); }
[data-skin="doom-64"] .shadow-sm { --tw-shadow: var(--shadow-sm); }
[data-skin="doom-64"] .shadow { --tw-shadow: var(--shadow); }
[data-skin="doom-64"] .shadow-md { --tw-shadow: var(--shadow-md); }
[data-skin="doom-64"] .shadow-lg { --tw-shadow: var(--shadow-lg); }
[data-skin="doom-64"] .shadow-xl { --tw-shadow: var(--shadow-xl); }
